#include <DHT.h>
#define DHTPIN {{dht_pin}}
#define DHTTYPE {{dht_type}}
DHT dht(DHTPIN, DHTTYPE);

void setup() {
  Serial.begin(115200);
  dht.begin();
}

void loop() {
  float h = dht.readHumidity();
  float t = dht.readTemperature();
  if (!isnan(h) && !isnan(t)) {
    Serial.print("T="); Serial.print(t);
    Serial.print(" H="); Serial.println(h);
  }
  delay(2000);
}
